import{_ as o,l as i,o as e,c as l,v as t,p as s,x as r,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"高精度算术","description":"","frontmatter":{"title":"高精度算术","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bignum-arith.md","filePath":"cs/bignum-arith.md","lastUpdated":1789023840000}'),c={name:"cs/bignum-arith.md"};function u(m,a,_,f,A,b){const n=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="高精度算术" tabindex="-1">高精度算术 <a class="header-anchor" href="#高精度算术" aria-label="Permalink to &quot;高精度算术&quot;">​</a></h1><div class="epigraph"><p>机器字装不下时，把整数当基 $B$ 的多项式；加减 $O(n)$，小学乘 $O(n^2)$，除法用规范化试商。</p><footer>—— 据 Knuth, The Art of Computer Programming, 卷 2；CLRS 第 31 章整理</footer></div><p>上一课<a href="/cs/fast-exponentiation">快速幂</a>假定一次乘是 \\(O(1)\\) 或 \\(O(k^\\omega)\\)。大整数的一次乘本身随位数涨。缺口是<strong>表示与小学算法</strong>：基 \\(10^9\\) 或 \\(2^{32}\\) 的数组，符号、进位、比较。后课 Karatsuba 才拆乘。不重写模意义下的小模运算。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(n\\) 位（基 \\(B\\) 下 \\(n\\) 个数字）加减从低位进位，\\(O(n)\\)。乘法：每位对每位，\\(O(n^2)\\)。除法：Knuth 的规范化除（D 算法），试商，最坏每位常数次修正。比较、移位、gcd 用欧几里得，代价由除法主导。</p><p>缺口是正确进位与试商，不是 FFT。负数用符号–幅度或补码数组，全程一种。</p><h3 id="基不是十进制的审美" tabindex="-1">基不是十进制的审美 <a class="header-anchor" href="#基不是十进制的审美" aria-label="Permalink to &quot;基不是十进制的审美&quot;">​</a></h3><p>选 \\(B\\) 使 \\(B^2\\) 不溢出机器字，或用宽寄存器。十进制只为 I/O。不要每位用 <code>char</code> 存 0–9 当高性能默认。</p><p><span class="marginnote">Knuth TAOCP 卷 2 是大数算术的标准出处。后课 Karatsuba \\(O(n^{\\log_2 3})\\)，再后 FFT 近 \\(n\\log n\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>约定小端或大端。乘：结果 \\(2n\\) 位。除法先对齐被除数。模幂：平方乘 + 本课乘。输出再转十进制。</p>',11)),(e(),s(p,null,{default:r(()=>[h(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20DIG%5B%22%E5%9F%BA%20B%20%E6%95%B0%E5%AD%97%E6%95%B0%E7%BB%84%22%5D%20--%3E%20ADD%5B%22%E5%8A%A0%E5%87%8F%20O(n)%22%5D%0A%20%20DIG%20--%3E%20MUL%5B%22%E5%B0%8F%E5%AD%A6%E4%B9%98%20O(n%5E2)%22%5D%0A%20%20DIG%20--%3E%20DIV%5B%22%E8%AF%95%E5%95%86%E9%99%A4%E6%B3%95%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>前导零、零的符号要约定。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>进位是基 \\(B\\) 的多项式加法。乘法是卷积，小学即朴素卷积。除法是乘法的逆，试商来自最高位估计。与浮点：大整数精确，位数由输入决定；浮点是近似。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 Montgomery 模乘细节（密码实现）。不写任意精度浮点。后课默认：大整数 = 数组 + 小学四则；乘可被更快算法替换。下一课 Karatsuba。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>大整数是基 \\(B\\) 多项式。</li><li>加减线性；小学乘平方；除法试商。</li><li>一次「乘」的代价从此不再 \\(O(1)\\)。</li><li>出处：Knuth TAOCP 卷 2。</li></ul>',7))])}const T=o(c,[["render",u]]);export{E as __pageData,T as default};
